 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The bottom-right 9 pattern is the marker for the large analogous 5 object.
    # Recolor the main contiguous 5 mass (the block spanning rows 12-16, cols 3-10)
    # to 9, preserving all other grid cells.
    cells = []
    for r in range(12,17):
        for c in range(3,11):
            if grid[r][c] == 5:
                cells.append((r,c))
    for r,c in cells:
        out[r][c] = 9
    return out
",
